"""
routes/diff.py — Task Worktree & Git Diff Inspection API
Supports:
  - GET /api/diff/<task_id>
"""
from __future__ import annotations

import os
import subprocess
from flask import Blueprint, jsonify, request
from auth_system import token_required

diff_bp = Blueprint("diff", __name__)
WORKSPACE_BASE = os.path.join(os.getcwd(), "workspace")


@diff_bp.route("/api/diff/<task_id>", methods=["GET"])
@diff_bp.route("/api/worktrees/<task_id>/diff", methods=["GET"])
@token_required
def get_diff(task_id: str):
    """Retrieve git / unified diff generated by a task in its workspace or worktree."""
    diff_text = ""
    base = os.path.realpath(os.path.join(WORKSPACE_BASE, task_id))

    # 1. If it's a git repo in workspace directory, run git diff
    if os.path.isdir(base) and os.path.isdir(os.path.join(base, ".git")):
        try:
            res = subprocess.run(
                ["git", "diff", "HEAD"],
                cwd=base,
                capture_output=True,
                text=True,
                timeout=5,
            )
            diff_text = res.stdout or ""
        except Exception:
            diff_text = ""

    # 2. Check durable state execution result
    if not diff_text:
        try:
            import json
            from execution import durable_state
            store = durable_state.get_store()
            rec = store.fetch(task_id)
            if rec:
                res_obj = json.loads(rec.get("result_json") or "{}")
                if res_obj.get("diff"):
                    diff_text = res_obj["diff"]
                elif rec.get("payload_json"):
                    payload = json.loads(rec.get("payload_json") or "{}")
                    wt_id = payload.get("worktree_id")
                    if wt_id:
                        from execution.worktree import worktree_diff
                        diff_text = worktree_diff(wt_id)
        except Exception:
            pass

    # 3. Direct worktree lookup by id
    if not diff_text:
        try:
            from execution.worktree import worktree_diff
            diff_text = worktree_diff(task_id)
        except Exception:
            pass

    return jsonify({
        "ok": True,
        "task_id": task_id,
        "diff": diff_text,
        "lines": diff_text.splitlines(),
        "files_changed": len([ln for ln in diff_text.splitlines() if ln.startswith("+++ b/")]),
    })
